def find_path(graph, start, goal):
    if not graph:
        return None
    if start == goal:
        return [start]

    explored = set()
    path_stack = [(start, [start])]  # Stack of (node, path)
    while path_stack:
        (node, path) = path_stack.pop()
        explored.add(node)
        for x, y in graph[node]:
            if (x, y) not in explored:
                if (x, y) == goal:
                    return path + [(x, y)]
                else:
                    path_stack.append(((x, y), path + [(x, y)]))  # Append the node and path to the stack
    return None

