    if not by_cx_and_p:
        by_cx_and_p = lambda x, y: set()
        # by_cx_and_p(x, y) -> set of nodes reachable from x with path of length y

    if not by_tx_and_p:
        by_tx_and_p = lambda x, y: set()
        # by_tx_and_p(x, y) -> set of nodes reachable from x with path of length y

    if not by_cx_and_guids:
