        # by_cx_and_guids(x) -> set of nodes reachable from x with any path

    if not by_tx_and_guids:
        by_tx_and_guids = lambda y: set()
        # by_tx_and_guids(y) -> set of nodes reachable from any node with path of length y

    if not by_dx_and_guids:
