        # by_dx_and_guids(x, y) -> set of nodes reachable from x with path of length y

    if not by_x_and_guids:
        by_x_and_guids = lambda y: set()
        # by_x_and_guids(y) -> set of nodes reachable from any node with path of length y

    if graph is None or start not in graph or goal not in graph:
        return None

    if start == goal:
        return [start]  # Goal is the start node

    explored.add(start)
    if start in graph:
        for node in graph[start]:
